import csv
# Look at unique house_rules entries for accommodations
rules = {}
with open('/Users/wangjinhua/Library/Caches/VistaExperiments/formal-task007-3x3-minimaxm3-20260821-02-noskill-replicate-01/workspace/data/accommodations/clean_accommodations_2022.csv', 'r') as f:
