import csv

# Find restaurants in our target cities, with EXACT cuisine match
target_cities = ['Minneapolis', 'Cleveland', 'Columbus', 'Cincinnati']

# Use first match in cuisines list with rating >= 3 to ensure quality
for cuisine in ['American', 'Mediterranean', 'Chinese', 'Italian']:
    print(f"\n=== {cuisine} ===")
    found_per_city = {}
    with open('/Users/wangjinhua/Library/Caches/VistaExperiments/formal-task007-3x3-minimaxm3-20260821-02-noskill-replicate-01/workspace/data/restaurants/clean_restaurant_2022.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            city = row['City']
            if city in target_cities and city not in found_per_city:
                cuisines = row['Cuisines']
                # split by comma and check exact match
                cuisine_list = [c.strip() for c in cuisines.split(',')]
                if cuisine in cuisine_list:
                    try:
                        cost = float(row['Average Cost']) if row['Average Cost'] else 0
                        rating = float(row['Aggregate Rating']) if row['Aggregate Rating'] else 0
                        found_per_city[city] = (row['Name'], cost, rating, cuisines)
                    except:
                        pass
    for city in target_cities:
        if city in found_per_city:
            name, cost, rating, cuisines = found_per_city[city]
            print(f"{city}\t{cost}\t{rating}\t{name}\t{cuisines}")
        else:
            print(f"{city}\tNOT FOUND")
EOF

